insert into saved values('cash',pg_temp.cash(2001));
insert into tap_results select lives_ok($$select public.agri_command('record_sale',(select data from saved where name='cash'))$$,'Owner can apply a ten-percent product-line discount');
insert into tap_results select is(public.agri_command('record_sale',(select data from saved where name='cash'))->>'status','duplicate','Original discounted cash retry posts once');
insert into tap_results select is(public.agri_command('record_sale',(select data from saved where name='cash')||jsonb_build_object('total',26000))->>'status','review','A changed discounted request cannot overwrite the original');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',pg_temp.cash(2002)||jsonb_build_object('total',28000))$$,'P0001','Invalid cash or sale total','Forged discounted totals are refused');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',jsonb_set(pg_temp.cash(2002),'{items,0,discountBps}','-1'))$$,'P0001','Discount percentage must use whole basis points','Negative discounts are refused');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',jsonb_set(pg_temp.cash(2002),'{items,0,discountBps}','10001'))$$,'P0001','Discount must be between 0 and 100 percent','Discounts above 100 percent are refused');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',jsonb_set(pg_temp.cash(2002),'{items,0,discountBps}','null'))$$,'P0001','Discount percentage must use whole basis points','An explicit null discount cannot bypass validation');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',jsonb_set(pg_temp.cash(2002),'{items,0,discountBps}','1.5'))$$,'P0001','Discount percentage must use whole basis points','Fractional basis points are refused');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',jsonb_set(pg_temp.cash(2002),'{items,0,unitPrice}','9000'))$$,'P0001','Price does not match the recorded catalog version','A discount cannot disguise a forged catalog price');
insert into tap_results select lives_ok($$select public.agri_command('partial_refund_sale',pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(2001),'refundId',pg_temp.i(2101),'shiftId',(select id from public.cashier_shifts where closed_at is null),'expectedRefundVersion',0,'expectedAmount',9000,'reference','TEST discounted return','reason','TEST no physical goods returned','physicalConfirmed',true,'items',jsonb_build_array(jsonb_build_object('lineIndex',0,'quantity','1','returnedQuantity','0','disposition','not_returned'))))$$,'Partial refund uses the discounted amount per original quantity');
insert into tap_results select lives_ok($$select public.agri_command('partial_refund_sale',pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(2001),'refundId',pg_temp.i(2102),'shiftId',(select id from public.cashier_shifts where closed_at is null),'expectedRefundVersion',1,'expectedAmount',18000,'reference','TEST discounted remainder','reason','TEST remaining actual paid amount','physicalConfirmed',true,'items',jsonb_build_array(jsonb_build_object('lineIndex',0,'quantity','2','returnedQuantity','0','disposition','not_returned'))))$$,'Remaining refund cannot refund the undiscounted price');
insert into tap_results select lives_ok($$select public.agri_command('record_sale',pg_temp.cash(2002,0))$$,'Zero discount preserves ordinary cash checkout');
insert into tap_results select lives_ok($$select public.agri_command('record_sale',pg_temp.cash(2003,10000))$$,'An explicitly authorized 100-percent line is a zero-cash sale');
insert into tap_results select lives_ok($$select public.agri_command('record_sale',pg_temp.cash(2004,1250))$$,'Branch cashier may enter a fractional percentage');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',pg_temp.cash(2005))$$,'42501','Only the owner or cashier may apply a product discount','Manager does not inherit the new owner/cashier discount permission');
insert into tap_results select lives_ok($$select public.agri_command('record_sale',pg_temp.cash(2006,0))$$,'Existing manager cash checkout without a discount remains valid');
insert into saved values('credit',jsonb_set(pg_temp.sale(2201,60),'{items,0}',(pg_temp.sale(2201,60)#>'{items,0}')||jsonb_build_object('discountBps',1000,'lineTotal',90000))||jsonb_build_object('total',90000));
insert into tap_results select lives_ok($$select public.agri_command('record_credit_sale',(select data from saved where name='credit'))$$,'Credit checkout applies the same percentage arithmetic');
insert into tap_results select is(pg_temp.book()->>'outstanding','70000','Credit debt is the discounted total less the actual down payment');
insert into tap_results select is(public.agri_command('record_credit_sale',(select data from saved where name='credit'))->>'duplicate','true','Discounted credit retry is idempotent');
insert into tap_results select throws_ok($$select public.agri_command('record_credit_sale',jsonb_set((select data from saved where name='credit')||jsonb_build_object('requestId',pg_temp.i(2202),'officialReference','TEST-FORGED'),'{items,0,lineTotal}','100000'))$$,'P0001','Sale line amount does not match its original price','Credit server rejects a forged discounted line total');
insert into tap_results select is((select total from public.sales where id=pg_temp.i(2001)),27000::bigint,'Saved sale amount is the net amount');
insert into tap_results select is((select price from public.sale_items where sale_id=pg_temp.i(2001)),10000::bigint,'Original unit price remains on the immutable sale line');
insert into tap_results select is((select sum(amount) from public.payments where sale_id=pg_temp.i(2001)),0::numeric,'Split refunds return exactly the original discounted cash');
insert into tap_results select is((select payload#>>'{items,0,discountBps}' from public.sales where id=pg_temp.i(2004)),'1250','Entered fractional percent is retained in receipt evidence');
insert into tap_results select is((select count(*) from public.unit_prices),1::bigint,'Discounts do not create or change catalog price versions');
insert into tap_results select is((select quantity from public.branch_inventory where product_id=pg_temp.i(301)),75::numeric,'Only actual sold quantities affect stock, including free goods');
insert into tap_results select * from finish();select line from tap_results;
